"""
    Convert meters to feet.

    :param float meters: meters
    :return: feet
    :rtype: float

    """
def m2ft(meters: float) -> float {
    if not isinstance(meters, (float, int)) {
        return 0;
    }
    return (meters * 3.28084);
}

