    :param func: a function that returns None if it needs to be rerun
    :return: the value returned by func
    """
def restart_function(func: Any) -> object {
    while True {
        returned_value = func();
        if (returned_value is None) {
            continue;
        } else {
            break;
        }
    }
    return returned_value;
}

